def predict_output(grid):
    h, w = len(grid), len(grid[0])

    # Find background
    flat = [val for row in grid for val in row]
    bg = Counter(flat).most_common(1)[0][0]

    # Copy grid as base for output
    out = [row[:] for row in grid]

    # Find marker groups (pairs of adjacent identical pixels)
    # Look for horizontal pairs first (same row, consecutive cols)
    marker_groups = []
    visited = set()

    for r in range(h):
        cscan = [c for c in range(w)]

        # Find contiguous segments of identical non-bg values
        segs = []
        current_start, current_val = None, None
        for c in cscan:
            val = grid[r][c]
            if val == bg:
                if current_start is not None:
                    segs.append((current_start, current_val, c))
                    current_start, current_val = None, None
            else:
                if current_start is None:
                    current_start = c
                    current_val = val
                elif val != current_val:
                    segs.append((current_start, current_val, c))
                    current_start, current_val = c, val
        if current_start is not None:
            segs.append((current_start, current_val, c))

        for start, val, end in segs:
            if val != bg:
                # Check if we already have segment with this value (marker should have two groups)
                if val not in {g['val'] for g in marker_groups}:
                    marker_groups.append({
                        'rows': [r],
                        'start': start,
                        'end': end,
                        'val': val
                    })

    print(f"Marker groups found: {marker_groups}")

    # Find secondary color pixels
    # These are non-bg pixels not part of markers
    secondary_colors = set()
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val != bg and val not in [g['val'] for g in marker_groups]:
                secondary_colors.add(val)

    print(f"Secondary colors: {secondary_colors}")

    for sc in sorted(secondary_colors):
        cells = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == sc]
        print(f"Secondary color {sc} at: {cells}")

    return out

