def predict_output(grid_in):
    h, w = len(grid_in), len(grid_in[0])

    # Find background
    bg = Counter([v for row in grid_in for v in row]).most_common(1)[0][0]

    # Find marker value - the non-bg values that form horizontal segments
    # Group contiguous non-bg values by value and row
    marker_groups = []
    for r in range(h):
        segments = []
        start = None
        prev_val = None
        for c, val in enumerate(grid_in[r]):
            if val != bg:
                if start is None:
                    start = c
                    prev_val = val
                elif val != prev_val:
                    segments.append((start, prev_val, c-1))
                    start = c
                    prev_val = val
            else:
                if start is not None:
                    segments.append((start, prev_val, c-1))
                    start = None
                    prev_val = None
        for start, val, end in segments:
            if len(range(start, end+1)) > 1 or (len(range(start, end+1)) == 1 and not any(v == val and sum(1 for r2 in range(h) for c2 in range(w) if r2 != r and grid_in[r2][c2] == val) < 5)):
                # Heuristic: horizontal segments of significant length or isolated special cells
                pass

    # Simpler approach: find all marker groups
    all_non_bg = [(r,c,v) for r in range(h) for c in range(w) for v in [grid_in[r][c]] if v != bg]
    non_bg_by_val = {}
    for r, c, v in all_non_bg:
        if v not in non_bg_by_val:
            non_bg_by_val[v] = []
        non_bg_by_val[v].append((r, c))

    # Find marker value - typically forms longer horizontal segments
    marker_val = None
    marker_rows = set()
    for val, positions in sorted(non_bg_by_val.items()):
        # Check if this forms long horizontal segments
        row_counts = Counter(r for r,c in positions)
        max_segment = max(row_counts.values()) if row_counts else 0
        if max_segment >= 2 or (max_segment == 1 and len(positions) >= 6):
            marker_val = val
            marker_rows = {r for r,_ in positions}
            break

    print(f"Marker value: {marker_val}")
    print(f"Marker rows: {sorted(marker_rows)}")

    if marker_val is None:
        # Fallback: use most common non-bg value
        non_bg_vals = Counter(v for r in range(h) for c in range(w) for v in [grid_in[r][c]] if v != bg)
        marker_val = non_bg_vals.most_common(1)[0][0]
        marker_rows = set(r for r in range(h) for c in range(w) if grid_in[r][c] == marker_val)

    # Find secondary color(s)
    sec_vals = [v for v in non_bg_by_val.keys() if v != marker_val]
    sec_val = sec_vals[0] if sec_vals else None

    print(f"Secondary value: {sec_val}")

    if sec_val is None:
        return [row[:] for row in grid_in]

    # Identify top vs bottom marker rows
    mid_h = h / 2
    top_marker_rows = {r for r in marker_rows if r < mid_h}
    bottom_marker_rows = {r for r in marker_rows if r >= mid_h}

    print(f"Top marker rows: {sorted(top_marker_rows)}")
    print(f"Bottom marker rows: {sorted(bottom_marker_rows)}")

    # Determine stripe columns for each marker side
    def get_stripe_cols_for_rows(rows):
        cols = set()
        for r in rows:
            for c in range(w):
                if grid_in[r][c] == marker_val:
                    cols.add(c)
        return cols

    top_cols = get_stripe_cols_for_rows(top_marker_rows)
    bottom_cols = get_stripe_cols_for_rows(bottom_marker_rows)

    print(f"Top stripe columns: {sorted(top_cols)}")
    print(f"Bottom stripe columns: {sorted(bottom_cols)}")

    # Create output grid
    out = [row[:] for row in grid_in]

    # Fill stripes
    for c in sorted(top_cols):
        # Fill downward from top marker to just before bottom marker
        for r in range(min(max(marker_rows) + 1, h)):
            if r <= min(top_marker_rows):
                continue
            out[r][c] = sec_val

    for c in sorted(bottom_cols):
        # Fill upward from bottom marker to row 0
        for r in range(max(marker_rows) - 1, -1, -1):
            out[r][c] = sec_val

    # Convert original secondary pixels to 4
    for r in range(h):
        for c in range(w):
            if grid_in[r][c] == sec_val:
                out[r][c] = 4

    return out

